package handler

import (
	"context"
	"regexp"
	"strconv"
	"strings"

	"github.com/cristianadrielbraun/gofer/internal/i18n"
	imapclient "github.com/cristianadrielbraun/gofer/internal/mail/imap"
)

// Many messages a user sees start deep in the handlers as English text,
// carried by errors and reasons. serverText shows such a text in the
// request's language where it reaches the user. A text it doesn't know,
// such as one a mail or calendar server wrote, stays as it is.
func serverText(ctx context.Context, text string) string {
	trimmed := strings.TrimSpace(text)
	if key, ok := serverTextKeys[trimmed]; ok {
		return i18n.T(ctx, key)
	}
	// A pattern that leaves its match as it was didn't know the text; a
	// later pattern or prefix may.
	for _, pattern := range serverTextPatterns {
		if match := pattern.re.FindStringSubmatch(trimmed); match != nil {
			if translated := pattern.text(ctx, match); translated != match[0] {
				return translated
			}
		}
	}
	for _, prefix := range serverTextPrefixes {
		if detail, ok := strings.CutPrefix(trimmed, prefix.english); ok {
			return i18n.T(ctx, prefix.key, "detail", serverText(ctx, detail))
		}
	}
	// The auth package's messages reach some pages this way too.
	if translated := authText(ctx, trimmed); translated != trimmed {
		return translated
	}
	return text
}

// serverTextPatterns are messages with numbers or names in them.
var serverTextPatterns = []struct {
	re   *regexp.Regexp
	text func(ctx context.Context, match []string) string
}{
	{regexp.MustCompile(`^(\d+) message files?$`), func(ctx context.Context, m []string) string {
		return i18n.N(ctx, "server.import.message_files", atoi(m[1]), "count", i18n.Number(ctx, atoi(m[1])))
	}},
	{regexp.MustCompile(`^(.+)/ \((\d+) message files?\)$`), func(ctx context.Context, m []string) string {
		return m[1] + "/ (" + i18n.N(ctx, "server.import.message_files", atoi(m[2]), "count", i18n.Number(ctx, atoi(m[2]))) + ")"
	}},
	{regexp.MustCompile(`^Connected to (\S+) \(mail account (.+)\)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.jmap_connected", "url", m[1], "account", m[2])
	}},
	{regexp.MustCompile(`^([A-Z]+) server (\S+) is on a private network; it needs a private target exception under Mail security$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.private_network", "protocol", m[1], "endpoint", m[2])
	}},
	{regexp.MustCompile(`^(IMAP|SMTP|HTTP) plaintext connections require an admin-approved server exception$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.plaintext_needs_exception", "protocol", m[1])
	}},
	{regexp.MustCompile(`^Gofer won't connect to (.+?) without encryption; an administrator can add an HTTP plaintext exception for (\S+) under Mail security$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.http_plaintext_refused", "target", m[1], "endpoint", m[2])
	}},
	{regexp.MustCompile(`^Gofer won't send JMAP requests to (.+) without encryption$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.jmap_plaintext_refused", "target", m[1])
	}},
	{regexp.MustCompile(`^(?:(\S+): )?the JMAP server rejected the username or password \(server said: (.*)\)$`), func(ctx context.Context, m []string) string {
		text := i18n.T(ctx, "server.pattern.jmap_rejected", "reason", m[2])
		if m[1] != "" {
			return m[1] + ": " + text
		}
		return text
	}},
	{regexp.MustCompile(`^no JMAP mail server found \((.*)\)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.jmap_not_found", "detail", m[1])
	}},
	{regexp.MustCompile(`^message is (\d+) bytes, but the SMTP server accepts at most (\d+) bytes$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.smtp_too_large", "size", i18n.Number(ctx, atoi(m[1])), "limit", i18n.Number(ctx, atoi(m[2])))
	}},
	{regexp.MustCompile(`^(.+) did not say where new calendars go$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.caldav_no_home", "server", m[1])
	}},
	{regexp.MustCompile(`^no calendars were returned from (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.caldav_no_calendars", "server", m[1])
	}},
	{regexp.MustCompile(`^(Google|Microsoft) did not let this account create calendars\. Reconnect the account from its actions menu, then try again$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.create_calendar_denied", "provider", m[1])
	}},
	{regexp.MustCompile(`^(Google|Microsoft) did not create the calendar: (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.create_calendar_failed", "provider", m[1], "detail", m[2])
	}},
	{regexp.MustCompile(`^(Gmail|Outlook) has multiple contacts with (.+); (resolve those copies|choose the copy to use) before enabling Gofer Sync$`), func(ctx context.Context, m []string) string {
		if m[3] == "resolve those copies" {
			return i18n.T(ctx, "server.pattern.duplicate_contacts_resolve", "provider", m[1], "contact", m[2])
		}
		return i18n.T(ctx, "server.pattern.duplicate_contacts_choose", "provider", m[1], "contact", m[2])
	}},
	{regexp.MustCompile(`^contact avatar exceeds (\d+) MB$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.avatar_too_large", "size", m[1])
	}},
	{regexp.MustCompile(`^message is too large: estimated (.+) after encoding\. The send limit is (.+) total, including attachments$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.send_too_large", "size", m[1], "limit", m[2])
	}},
	{regexp.MustCompile(`^"(.*)" is not a valid pattern\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.rule_bad_pattern", "pattern", m[1])
	}},
	{regexp.MustCompile(`^Could not auto-discover CardDAV for this account\. Tried (.+) and (.+), but the server did not return CardDAV account details\. Enter the provider's CardDAV base URL, such as https://dav\.example\.com/ or https://mail\.example\.com/SOGo/dav/, then try again$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.carddav_discover_two", "first", m[1], "second", m[2])
	}},
	{regexp.MustCompile(`^Could not auto-discover CardDAV for this account\. Tried (.+), but none returned CardDAV account details\. Enter the provider's CardDAV base URL, such as https://dav\.example\.com/ or https://mail\.example\.com/SOGo/dav/, then try again$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.carddav_discover_many", "tried", m[1])
	}},
	{regexp.MustCompile(`^CardDAV discovery timed out\. Tried (.+)\. Enter the provider's exact CardDAV base URL and try again$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.carddav_discover_timeout", "tried", m[1])
	}},
	{regexp.MustCompile(`^Could not auto-discover CardDAV for (.+)\. The server did not return CardDAV account details$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.carddav_discover_one", "url", m[1])
	}},
	{regexp.MustCompile(`^Google Calendar access is not authorized for account (.+); reconnect Google to grant Calendar access$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.google_calendar_unauthorized", "account", m[1])
	}},
	{regexp.MustCompile(`^no refresh token available for account (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.no_refresh_token", "account", m[1])
	}},
	{regexp.MustCompile(`^the server did not (rename|delete) the (address book|calendar): (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.dav_"+m[1]+"_"+strings.ReplaceAll(m[2], " ", "_"), "detail", m[3])
	}},
	{regexp.MustCompile(`^the server did not confirm renaming the (address book|calendar): (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.dav_rename_unconfirmed_"+strings.ReplaceAll(m[1], " ", "_"), "detail", m[2])
	}},
	{regexp.MustCompile(`^This message is (\d+) MB, so it wasn't downloaded automatically\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.message_large", "size", m[1])
	}},
	{regexp.MustCompile(`^This message is larger than (\d+) MB, so it wasn't downloaded automatically\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.message_larger_than", "size", m[1])
	}},
	{regexp.MustCompile(`^This message is (\d+) MB\. Gofer can show messages up to (\d+) MB\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.message_oversize", "size", m[1], "limit", m[2])
	}},
	{regexp.MustCompile(`^This message is larger than the (\d+) MB Gofer can show\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.message_over_limit", "limit", m[1])
	}},
	{regexp.MustCompile(`^(“.+”|An event): (.+)\.$`), func(ctx context.Context, m []string) string {
		if m[1] == "An event" {
			return i18n.T(ctx, "server.pattern.import_reason_unnamed", "reason", serverTextOf(ctx, m[2]))
		}
		return i18n.T(ctx, "server.pattern.import_reason", "event", strings.Trim(m[1], "“”"), "reason", serverTextOf(ctx, m[2]))
	}},
	{regexp.MustCompile(`^the calendar refused it \(HTTP (\d+)\)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.calendar_refused_http", "status", m[1])
	}},
	{regexp.MustCompile(`^Microsoft calendars have no repeat pattern like its (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.microsoft_no_repeat", "rule", m[1])
	}},
	{regexp.MustCompile(`^A folder named “(.+)” is already there\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.folder_exists", "name", m[1])
	}},
	{regexp.MustCompile(`^“(.+)” is one of the account's own folders, so it can't be (renamed|deleted|moved)\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.own_folder_"+m[2], "name", m[1])
	}},
	{regexp.MustCompile(`^“(.+)”, inside this folder, is one of the account's own folders, so this folder can't be (deleted|moved)\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.own_child_"+m[2], "name", m[1])
	}},
	{regexp.MustCompile(`^“(.+)” is already in Trash\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.folder_in_trash", "name", m[1])
	}},
	{regexp.MustCompile(`^This account has no Trash folder to put “(.+)” in\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.no_trash_for", "name", m[1])
	}},
	{regexp.MustCompile(`^“(.+)” couldn't be moved to Trash\. (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.folder_trash_failed", "name", m[1], "detail", serverTextOf(ctx, m[2]))
	}},
	{regexp.MustCompile(`^“(.+)” isn't in Trash\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.folder_not_in_trash", "name", m[1])
	}},
	{regexp.MustCompile(`^There's already a label named “(.+)”\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.label_exists", "name", m[1])
	}},
	{regexp.MustCompile(`^A folder name can\'t contain "(.+)"\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.folder_name_char", "char", m[1])
	}},
	{regexp.MustCompile(`^Your Gofer administrator doesn't allow mailboxes with @(.+) addresses\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.allowlist_domain", "domain", m[1])
	}},
	{regexp.MustCompile(`^Your Gofer administrator doesn't allow connecting to the mail server (.+)\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.allowlist_server", "server", m[1])
	}},
	{regexp.MustCompile(`^Your Gofer administrator doesn't allow (.+) mailboxes\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.allowlist_provider", "provider", m[1])
	}},
	{regexp.MustCompile(`^"(.*)" is not an email address(\.?)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.not_an_address"+map[string]string{"": "", ".": "_sentence"}[m[2]], "address", m[1])
	}},
	{regexp.MustCompile(`^Gofer can't do this: (.+)\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.invitation_refused", "reason", serverTextOf(ctx, m[1]))
	}},
	{regexp.MustCompile(`^Discovered (\d+) (Google calendar source\(s\)|Microsoft calendar source\(s\)|CalDAV calendar\(s\)|JMAP calendar\(s\))\. (.+)$`), func(ctx context.Context, m []string) string {
		kind := map[string]string{"Google calendar source(s)": "google", "Microsoft calendar source(s)": "microsoft", "CalDAV calendar(s)": "caldav", "JMAP calendar(s)": "jmap"}[m[2]]
		return i18n.N(ctx, "server.pattern.discovered."+kind, atoi(m[1]), "count", i18n.Number(ctx, atoi(m[1]))) + " " + serverTextOf(ctx, m[3])
	}},
	{regexp.MustCompile(`^Created the calendar "(.*)"\.$`), func(ctx context.Context, m []string) string {
		name, err := strconv.Unquote(`"` + m[1] + `"`)
		if err != nil {
			name = m[1]
		}
		return i18n.T(ctx, "server.pattern.calendar_created", "name", name)
	}},
	{regexp.MustCompile(`^Contacts synced for (.+): (\d+) imported or updated\.$`), func(ctx context.Context, m []string) string {
		return i18n.N(ctx, "server.pattern.contacts_synced_one_account", atoi(m[2]), "account", m[1], "count", i18n.Number(ctx, atoi(m[2])))
	}},
	{regexp.MustCompile(`^Contacts synced across (\d+) accounts: (\d+) imported or updated\.$`), func(ctx context.Context, m []string) string {
		return i18n.N(ctx, "server.pattern.contacts_synced_accounts", atoi(m[2]), "accounts", i18n.Number(ctx, atoi(m[1])), "count", i18n.Number(ctx, atoi(m[2])))
	}},
	{regexp.MustCompile(`^Mail sync started for (\d+) accounts\.$`), func(ctx context.Context, m []string) string {
		return i18n.N(ctx, "server.pattern.mail_sync_started", atoi(m[1]), "count", i18n.Number(ctx, atoi(m[1])))
	}},
	{regexp.MustCompile(`^Forward to at most (\d+) people at once\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.forward_limit", "count", m[1])
	}},
	{regexp.MustCompile(`^Use a name of at most (\d+) characters\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.name_limit", "count", m[1])
	}},
	{regexp.MustCompile(`^The file has more than (\d+) events\. Split it into smaller files\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.ics_too_many", "count", i18n.Number(ctx, atoi(m[1])))
	}},
	{regexp.MustCompile(`^The calendar server stopped accepting events after (\d+) of (\d+)\. Importing the file again into the same calendar skips the ones already added\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.ics_partial", "added", i18n.Number(ctx, atoi(m[1])), "total", i18n.Number(ctx, atoi(m[2])))
	}},
	{regexp.MustCompile(`^Import stopped after saving (\d+) (contact|contacts)\. The remaining contacts were not saved\.$`), func(ctx context.Context, m []string) string {
		return i18n.N(ctx, "server.pattern.contacts_import_stopped", atoi(m[1]), "count", i18n.Number(ctx, atoi(m[1])))
	}},
	{regexp.MustCompile(`^The provider does not let this account send as (.+)\. Send it through another SMTP server instead\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.send_as_denied", "address", m[1])
	}},
	{regexp.MustCompile(`^Invitation delivery is managed by (.+)\. Guest responses reflect the last calendar sync\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.delivery_managed", "provider", m[1])
	}},
	{regexp.MustCompile(`^CardDAV save failed: could not connect to (.+?): (.*)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.carddav_connect_failed", "book", m[1], "detail", m[2])
	}},
	{regexp.MustCompile(`^The (.+)\.$`), func(ctx context.Context, m []string) string {
		// A reconnect reason, as the mail body error writes it.
		if key, ok := serverTextKeys[m[1]]; ok {
			return i18n.T(ctx, "server.pattern.reconnect_reason", "reason", i18n.T(ctx, key))
		}
		return m[0]
	}},
	{regexp.MustCompile(`^(.+?) Refresh the calendar and reopen the event\.$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.refresh_reopen", "detail", serverTextOf(ctx, m[1]))
	}},
	{regexp.MustCompile(`^` + regexp.QuoteMeta(imapclient.LoginCooldownMessage) + `(?: \((.+)\))?$`), func(ctx context.Context, m []string) string {
		// The first refusal carries the server's own words.
		if m[1] != "" {
			return i18n.T(ctx, "server.pattern.imap_login_limited_detail", "detail", m[1])
		}
		return i18n.T(ctx, "server.error.imap_login_limited")
	}},
	{regexp.MustCompile(`^connect to (\S+?): (.+)$`), func(ctx context.Context, m []string) string {
		return i18n.T(ctx, "server.pattern.connect_to", "host", m[1], "detail", serverTextOf(ctx, m[2]))
	}},
}

// serverTextOf lets a pattern translate the rest of its message.
var serverTextOf func(ctx context.Context, text string) string

func init() { serverTextOf = serverText }

func atoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}

